import threading
import time
import signal
import os
from collections import OrderedDict
from contextlib import contextmanager


class ResourceLease:
    """Represents a cloud resource lease with TTL."""
    def __init__(self, resource_id, ttl=300):
        self.resource_id = resource_id
        self.ttl = ttl
        self.acquired_at = time.monotonic()
        self.released = False
        self._lock = threading.Lock()

    def is_expired(self):
        return time.monotonic() - self.acquired_at > self.ttl

    def release(self):
        with self._lock:
            if not self.released:
                self.released = True
                return True
            return False


class LeaseManager:
    """Manages resource leases with graceful shutdown support."""

    def __init__(self, max_leases=100):
        self._leases = OrderedDict()
        self._lock = threading.RLock()
        self._shutdown_event = threading.Event()
        self._drain_complete = threading.Event()
        self._active_operations = 0
        self._ops_lock = threading.Lock()
        self._cleanup_thread = None
        self._started = False

    def start(self):
        """Start the lease manager background tasks."""
        self._started = True
        self._cleanup_thread = threading.Thread(
            target=self._cleanup_loop, daemon=True
        )
        self._cleanup_thread.start()

    def _cleanup_loop(self):
        """Periodically clean up expired leases."""
        while not self._shutdown_event.is_set():
            self._purge_expired()
            self._shutdown_event.wait(timeout=10)

    def _purge_expired(self):
        """Remove expired leases from the manager."""
        with self._lock:
            expired = [
                rid for rid, lease in self._leases.items()
                if lease.is_expired()
            ]
            for rid in expired:
                lease = self._leases.pop(rid)
                lease.release()

    @contextmanager
    def _track_operation(self):
        """Track active operations for graceful shutdown."""
        with self._ops_lock:
            if self._shutdown_event.is_set():
                raise RuntimeError("Manager is shutting down")
            self._active_operations += 1
        try:
            yield
        finally:
            with self._ops_lock:
                self._active_operations -= 1
                if self._active_operations == 0 and self._shutdown_event.is_set():
                    self._drain_complete.set()

    def acquire_lease(self, resource_id, ttl=300):
        """Acquire a lease on a resource."""
        with self._track_operation():
            with self._lock:
                if resource_id in self._leases:
                    existing = self._leases[resource_id]
                    if not existing.is_expired():
                        raise ValueError(f"Lease already held: {resource_id}")
                    existing.release()
                lease = ResourceLease(resource_id, ttl)
                self._leases[resource_id] = lease
                return lease

    def release_lease(self, resource_id):
        """Release a specific lease."""
        with self._track_operation():
            with self._lock:
                if resource_id in self._leases:
                    lease = self._leases.pop(resource_id)
                    return lease.release()
            return False

    def graceful_shutdown(self, timeout=30):
        """Initiate graceful shutdown, waiting for operations to drain."""
        self._shutdown_event.set()

        # Check if we need to wait for operations
        needs_drain = False
        with self._ops_lock:
            if self._active_operations > 0:
                needs_drain = True

        if needs_drain:
            self._drain_complete.wait(timeout=timeout)

        # Release all remaining leases
        self._release_all_leases()

        if self._cleanup_thread:
            self._cleanup_thread.join(timeout=5)

    def _release_all_leases(self):
        """Release all held leases during shutdown."""
        with self._lock:
            lease_ids = list(self._leases.keys())
            # Release under the lock to prevent concurrent access
            for rid in lease_ids:
                lease = self._leases.pop(rid, None)
                if lease is not None:
                    lease.release()


class CloudInfraSDK:
    """High-level SDK for cloud infrastructure management."""

    def __init__(self):
        self._lease_manager = LeaseManager()
        self._lease_manager.start()
        self._register_signal_handlers()

    def _register_signal_handlers(self):
        """Register signal handlers for graceful shutdown."""
        try:
            signal.signal(signal.SIGTERM, self._handle_signal)
            signal.signal(signal.SIGINT, self._handle_signal)
        except (OSError, ValueError):
            pass  # Not in main thread

    def _handle_signal(self, signum, frame):
        """Handle shutdown signals."""
        threading.Thread(
            target=self._lease_manager.graceful_shutdown,
            kwargs={'timeout': 30}
        ).start()

    def acquire_resource(self, resource_id, ttl=300):
        """Acquire exclusive access to a cloud resource."""
        return self._lease_manager.acquire_lease(resource_id, ttl)

    def release_resource(self, resource_id):
        """Release a cloud resource."""
        return self._lease_manager.release_lease(resource_id)

    def shutdown(self, timeout=30):
        """Shutdown the SDK gracefully."""
        self._lease_manager.graceful_shutdown(timeout)
